        description: "O dragão conjura uma réplica perfeita em carne de um humanoide que tenha visto, do próprio tamanho ou menor, e se comprime nela, gerando também roupas adequadas. O processo leva 1 minuto, durante o qual o dragão fica Ocupado. Se parar ou for interrompido, o traje é destruído. Completo, o dragão pode permanecer no disfarce indefinidamente.\nA transformação tem os efeitos de Forma Humanoide, exceto que o disfarce não é ativamente mágico e não registra como magia para Detectar Magia e efeitos semelhantes. O dragão perde Retrair o Corpo enquanto transformado.\nSe sofrer um acerto crítico vestindo o disfarce, o traje é destruído e explode na hora. Isso tem os efeitos de Detonar Disfarce, exceto que as criaturas usam um grau de sucesso melhor do que o rolado.",
