        description: "12 m.\nA mera visão de um dragão empíreo motiva outras criaturas. Criaturas na aura ganham +1 de status em salvaguardas e testes de perícia. O dragão empíreo não pode se beneficiar da própria aura nem de outras ações que usem a aura, e pode excluir qualquer criatura de qualquer benefício da aura ou ação que a use.",
