        name: "Exibição Inquietante",
        originalName: "Disquieting Display",
        actionType: "two",
        description: "O gongorinan abre as fauces e revela as formas ali, fazendo os observadores questionarem o próprio corpo. Criaturas numa emanação de 9 m tentam Vontade CD 30; depois ficam imunes temporariamente a novas Exibições Inquietantes por 1 minuto.\nSucesso crítico Não é afetada.\nSucesso Desajeitada 1 por 1 rodada.\nFalha Desajeitada 2 e Atrasada 1 por 1 rodada.\nFalha crítica Como falha, mas por 1 minuto.",
