        description: "Salvaguarda Fortitude CD 30\nEstágio 1 Embotado 1 e sinais estéticos de virar animal, fungo ou planta (1 rodada)\nEstágio 2 Embotado 2 e Desajeitado 2 (1 rodada)\nEstágio 3 Embotado 4 e Desajeitado 4 (1 rodada)\nEstágio 4 as mudanças tomam o corpo por completo (1 rodada)\nEstágio 5 a vítima se transforma permanentemente em animal, fungo ou planta em mente e corpo como maldição permanente, e a aflição termina",
