        description: "27 m. Vontade CD 37\n\nAura (emoção, medo, mental). Quem entra na área pela primeira vez precisa passar em Vontade. Independente do resultado, fica imune temporariamente à Presença Aterradora desta criatura por 1 minuto.\nSucesso crítico não é afetado.\nSucesso Amedrontado 1.\nFalha Amedrontado 2.\nFalha crítica Amedrontado 3 e em fuga por 1 rodada.",
