        description: "O linnorm do gelo cospe uma rajada de gosma congelante e viscosa num cone de 18 m que causa 15d6 de frio (Reflexos CD 38).\nA gosma adere a quem é atingido e endurece em placas de gelo. Quem falha fica Imobilizado pelo gelo até passar num teste de Escapar CD 34 ou até ele ou um aliado Forçar Abertura no gelo (CD 34 em ambos os casos). No início do turno, uma criatura ainda imobilizada pelo gelo sofre 4d6 de frio. Outra criatura pode libertar o alvo causando um total de 20 de fogo ao alvo congelado. Sem intervenção, o gelo se desfaz em 1 minuto.\nCriaturas com o traço fogo não podem ser congeladas pelo Sopro de Lama Gélida. Criaturas voadoras caem se congeladas, e as que nadam sobem à superfície a 18 m por rodada.",
