        name: "Moldar Diabos",
        originalName: "Shape Devils",
        actionType: "passive",
        description: "O nessari remodela um grande número de orts numa emanação de 180 m em diabos mais poderosos para inchar as legiões do Inferno. Precisa ter disponíveis os orts da tabela abaixo.\nNível do diabo — Número de orts: 4 ou menos — 4; 5–6 — 8; 7–8 — 16; 9–10 — 32; 11–12 — 64; 13–14 — 128; 15–16 — 256; 17–18 — 512; 19–20 — 1.024.\nO nessari pode moldar 100 orts por dia, até o máximo de 1.100 em 11 dias. Diabos criados assim ficam sob o jugo do nessari e seguem suas ordens, exceto nessaris criados ou outros diabos de poder semelhante, que são sempre independentes. Por isso, poucos nessaris criam pares. Ao fim da atividade, o nessari tenta um teste incrivelmente difícil de Religião do nível do diabo desejado.\nSucesso crítico Molda dois diabos em vez de um.\nSucesso Molda um diabo do tipo e nível desejados.\nFalha O diabo moldado tem 2 níveis a menos que o pretendido.\nFalha crítica Não molda diabos e atrai a ira de um arquidiabo pelo desperdício.",
