    abilities: [
      {
        id: "raja-krodha-1-status-to-all-saves-vs-magic",
        name: "+2 de status em todas as salvaguardas vs. magia",
        originalName: "+2 Status to All Saves vs. Magic",
        actionType: "passive",
        description: "Ganha +2 de status em todas as salvaguardas contra magia.",
      },
      {
        id: "raja-krodha-knowledge-of-delusion",
        name: "Saber da Ilusão",
        originalName: "Knowledge of Delusion",
        actionType: "passive",
        description: "Uma criatura que falhe num teste de Recordar Conhecimento ou de Percepção para Procurar um raja-krodha fica Desprotegida até o fim do próximo turno.",
      },
      {
        id: "raja-krodha-reassert-fate",
        name: "Reafirmar o Destino",
        originalName: "Reassert Fate",
        actionType: "reaction",
        trigger: "Uma criatura a até 9 m usa um efeito de fortuna ou infortúnio",
        description: "O raja-krodha reafirma o fluxo do destino, instilando pavor profundo em quem tenta trapacear o papel escrito. Interrompe o efeito disparador, e quem disparou fica Amedrontado 2 e Desprotegido contra o raja-krodha até o fim do próximo turno.",
      },
      {
        id: "raja-krodha-change-shape",
        name: "Mudar Forma",
        originalName: "Change Shape",
        actionType: "one",
        description: "O raja-krodha assume a aparência de qualquer humanoide Médio. Isso não muda o Deslocamento nem os modificadores de ataque e dano dos Golpes, mas pode mudar o tipo de dano (em geral concussão). Perde o Golpe de presas a menos que a forma humanoide tenha presas ou ataque desarmado semelhante.\n\nA criatura muda de forma por tempo indefinido. Pode usar esta ação de novo para voltar à forma natural ou assumir outra forma. Salvo indicação em contrário, não pode usar Mudar Forma para parecer um indivíduo específico. Usar Mudar Forma conta como criar um disfarce para Personificar (Enganação). A transformação vence automaticamente as CDs de Percepção para decidir se a criatura é da ancestralidade ou do tipo em que se transformou, e ela ganha +4 de status na CD de Enganação para impedir que vejam através do disfarce. A habilidade lista as formas que pode assumir. A criatura não ganha habilidades especiais da nova forma, só o corpo: em cada forma, substitui Deslocamentos e Golpes normais, e pode mudar sentidos ou tamanho. Qualquer mudança está na ficha.",
      },
      {
        id: "raja-krodha-cruel-majesty",
        name: "Majestade Cruel",
        originalName: "Cruel Majesty",
        actionType: "one",
        requirements: "O rakshasa não está na forma verdadeira",
        description: "O rakshasa Muda de Forma para a forma verdadeira num espetáculo a um só tempo aterrador e majestoso. Criaturas a até 9 m precisam passar em Vontade CD 29 ou ficam Desprotegidas contra o rakshasa até o início do próximo turno dele, pasmas de admiração.",
      },
      {
        id: "raja-krodha-sneak-attack",
        name: "Ataque Furtivo",
        originalName: "Sneak Attack",
        actionType: "passive",
        description: "Os Golpes causam 2d6 extra de dano de precisão a alvos Desprotegidos.\n\nQuando a criatura Golpeia um alvo Desprotegido com arma corpo a corpo ágil ou de acuidade, ataque desarmado ágil ou de acuidade, ou ataque à distância, também causa o dano de precisão listado. Num ataque à distância com arma de arremesso, essa arma também precisa ser ágil ou de acuidade.",
      },
      {
        id: "raja-krodha-swallow-whole",
        name: "Engolir Inteiro",
        originalName: "Swallow Whole",
        actionType: "one",
        description: "Médio, 2d12+6 de concussão, Ruptura 15\n\nA criatura tenta engolir um alvo do tamanho listado ou menor que esteja agarrado ou imobilizado nas mandíbulas ou na boca. Se o alvo engolido for do tamanho máximo listado, não pode usar Engolir Inteiro de novo. Se for menor, em geral pode engolir mais; o Mestre define o máximo. A criatura faz um teste de Atletismo contra a CD de Reflexos do alvo. Se passar, engole. A boca ou as mandíbulas deixam de agarrar quem foi engolido, então a criatura pode usá-las de novo para Golpear ou Agarrar. Não pode atacar alvos que tenha engolido.\n\nUm alvo engolido fica agarrado, Atrasado 1, e precisa prender a respiração ou começa a sufocar. Sofre o dano listado ao ser engolido e no fim de cada turno enquanto estiver engolido. Se Escapar da condição de agarrado desta habilidade, sai pela boca — isso também solta qualquer outro alvo preso na boca ou nas mandíbulas. Quem está engolido só pode atacar a criatura com ataques desarmados ou armas de Bulk leve ou menor. A criatura que engoliu fica Desprotegida contra esse ataque. Se a criatura sofrer dano perfurante ou cortante igual ou maior que o valor de Ruptura listado num único ataque ou magia, o alvo se corta para fora. Quem se solta (Escapando ou se cortando) pode respirar na hora e sai no espaço da criatura.\n\nSe a criatura morrer, um alvo engolido pode ser libertado por criaturas adjacentes ao cadáver se gastarem um total combinado de 3 ações cortando-a com arma ou ataque desarmado que cause dano perfurante ou cortante.",
      },
      {
        id: "raja-krodha-grab",
        name: "Agarrar",
        originalName: "Grab",
        actionType: "one",
        requirements: "A última ação da criatura foi um Golpe bem-sucedido que lista Agarrar na entrada de dano, ou a criatura já tem um alvo agarrado ou imobilizado.",
        description: "Se usada depois de um Golpe, a criatura tenta Agarrar o alvo usando a parte do corpo com que atacou. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos. Em vez disso, a criatura pode usar Agarrar e escolher uma criatura que já esteja agarrando ou imobilizando com um apêndice que tenha Agarrar para estender automaticamente essa condição até o fim do próximo turno da criatura.",
      },
    ],
    summary: "Rakshasa da ira coroada. A máscara tigre já é a sentença.",
    recallKnowledge: [
      { label: "Espírito (Ocultismo)", dc: 27 },
    ],
    sourceId: SOURCE_MONSTER_CORE_ID,
