        actionType: "one",
        frequency: "uma vez por minuto",
        description: "Faça um Golpe contra uma árvore viva com o Machado Negro. Se acertar, a árvore vira cinza, você cura 250 PV e ganha o benefício de uma magia Regenerar de 6º círculo.",
